/bin/bash -lc "python - <<'PY'
from pathlib import Path
import zipfile, csv, io
from rdkit import Chem

path = Path('/work/v122/agent/candidate/result.zip')
expected = ['result1.csv', 'result2.csv', 'result3.csv', 'result.log']
errors = []
summary = []

if not path.exists():
    errors.append('candidate zip missing')
else:
    with zipfile.ZipFile(path, 'r') as z:
        names = z.namelist()
        if names "'!= expected:
            errors.append(f'"'entry order mismatch: {names"'!r}'"')
        for name in expected[:3]:
            try:
                text = z.read(name).decode('utf-8-sig')
            except Exception as e:
                errors.append(f'{name}: read/decode failed: {type(e).__name__}')
                continue
            reader = csv.DictReader(io.StringIO(text))
            if reader.fieldnames "'!= ['"'mol_smiles', 'route']:
                errors.append(f'{name}: bad header {reader.fieldnames"'!r}'"')
                continue
            rows = list(reader)
            seen = set()
            if len(rows) > 5:
                errors.append(f'{name}: too many rows {len(rows)}')
            for idx, row in enumerate(rows, 1):
                smi = row.get('mol_smiles', '')
                route = row.get('route', '')
                if smi in seen:
                    errors.append(f'{name}: duplicate mol_smiles at row {idx}')
                seen.add(smi)
                if Chem.MolFromSmiles(smi) is None:
                    errors.append(f'{name}: invalid mol_smiles at row {idx}')
                final = route.rsplit('>>', 1)[-1].strip()
                if final "'!= smi:
                    errors.append(f'"'{name}: route final product mismatch at row {idx}')
                if Chem.MolFromSmiles(final) is None:
                    errors.append(f'{name}: invalid final product at row {idx}')
            summary.append((name, len(rows), len(seen)))
        try:
            z.read('result.log')
        except Exception as e:
            errors.append(f'result.log read failed: {type(e).__name__}')

print('candidate', path)
print('entries_ok', not errors)
for name, rows, unique in summary:
    print(name, 'rows', rows, 'unique', unique)
if errors:
    print('errors')
    for e in errors:
        print(e)
    raise SystemExit(1)
print('validation passed')
PY"

